import os
import uuid

def generate_1mb_string():
    # os.urandom(512 * 1024) generates 512KB of random bytes.
    # .hex() converts it to a string where each byte is 2 hex characters,
    # resulting in exactly 1,048,576 characters (1MB).
    return os.urandom(512 * 1024).hex()

def main():
    directory = "tmp_logs"
    os.makedirs(directory, exist_ok=True)

    print(f"Starting infinite file generation in '{directory}'...")
    try:
        while True:
            filename = os.path.join(directory, f"log_{uuid.uuid4().hex}.txt")
            with open(filename, "w") as f:
                f.write(generate_1mb_string())
    except Exception as e:
        print(f"Process stopped: {e}")

if __name__ == "__main__":
    main()
